commits.patch:
diff --git a/src/knownhost.c b/src/knownhost.c
index 2bd41de..7779241 100644
--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -419,17 +419,17 @@ static int knownhost_parse_ipv4(const char *src, const char *end,
     return 1;
 }

-static int knownhost_parse_ipv6(const char *src, size_t len,
+static int knownhost_parse_ipv6(const char *src,
                                 unsigned char result[16])
 {
     unsigned short words[8];
     const char *p = src;
-    const char *end = src + len;
+    const char *end = src + strlen(src);
     size_t count = 0;
     int compressed = -1;
     size_t i;

-    if(!len)
+    if(p == end)
         return 0;

     memset(words, 0, sizeof(words));
@@ -552,6 +552,8 @@ static int knownhost_plain_match(const char *host, const char *known)
     const char *known_suffix;
     size_t host_len;
     size_t known_len;
+    char host_buf[64];
+    char known_buf[64];
     unsigned char host_binary[16];
     unsigned char known_binary[16];

@@ -567,8 +569,17 @@ static int knownhost_plain_match(const char *host, const char *known)
        strcmp(host_suffix, known_suffix))
         return 0;

-    if(!knownhost_parse_ipv6(host_address, host_len, host_binary) ||
-       !knownhost_parse_ipv6(known_address, known_len, known_binary))
+    /* ignore tokens that are too long to be IPv6 literals */
+    if(host_len > 46 || known_len > 46)
+        return 0;
+
+    memcpy(host_buf, host_address, host_len);
+    host_buf[host_len] = '\0';
+    memcpy(known_buf, known_address, known_len);
+    known_buf[known_len] = '\0';
+
+    if(!knownhost_parse_ipv6(host_buf, host_binary) ||
+       !knownhost_parse_ipv6(known_buf, known_binary))
         return 0;

     return !memcmp(host_binary, known_binary, sizeof(host_binary));

--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -552,8 +552,8 @@ static int knownhost_plain_match(const char *host, const char *known)
     const char *known_suffix;
     size_t host_len;
     size_t known_len;
-    char host_buf[64];
-    char known_buf[64];
+    char host_buf[46];
+    char known_buf[46];
     unsigned char host_binary[16];
     unsigned char known_binary[16];
